        type: 'dynamicField',
        mode: 'key-value',
        keyPlaceholder: 'key',
        valuePlaceholder: 'value',
        keyOptions: quantizationParametersTipList,
        visible:
          !!formData.model_engine && formData.model_engine === 'Transformers',
